    headers: { RSC: '"'1', 'Next-Router-Prefetch': '2' },
  })
  assert.equal(response.status, 200)
  const body = await response.text()
  assert.ok(body.includes(title))
  assert.ok(body.includes('Loading project details...'))
  assert.ok("'!body.includes(description))
  assert.ok(!body.includes('"'Recent activity'))
  console.log("'`${slug}: cached details remain excluded from subsequent prefetches`)
}
const response = await fetch('"'http://127.0.0.1:3000/projects/acme')
